17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
32	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        rejectDuplicateTelephone(telephone);
109	        owner.setTelephone(telephone);
110	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(java.time.LocalDate.now());
113	        }
114	        owner.setCustomerCode(assignCustomerCode(owner.getLastName()));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    /**
123	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
124	     * LAST3 is the upper-cased first three letters of the last name and NNNN is a global 4-digit
125	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
126	     *
127	     * @param lastName the owner's last name
128	     * @return the assigned customer code
129	     */
130	    private String assignCustomerCode(String lastName) {
131	        String name = lastName == null ? "" : lastName;
132	        String last3 = name.substring(0, Math.min(3, name.length()))
133	            .toUpperCase(java.util.Locale.ROOT);
134	        int sequence = this.clinicService.findAllOwners().size() + 1;
135	        return String.format("%s-%04d", last3, sequence);
136	    }
137	
138	    /**
139	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
140	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
141	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
142	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
143	     * {@code "+61412345678"}. The E.164 value is stored and returned.
144	     *
145	     * @param telephone the raw telephone as submitted
146	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
147	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
148	     */
149	    private String normalizeTelephone(String telephone) {
150	        String raw = telephone == null ? "" : telephone.trim();
151	        boolean hasCountryCode = raw.startsWith("+");
152	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
153	        if (hasCountryCode) {
154	            cleaned = cleaned.substring(1);
155	        }
156	        String digits;
157	        if (hasCountryCode) {
158	            digits = cleaned;
159	        } else {
160	            if (cleaned.startsWith("0")) {
161	                cleaned = cleaned.substring(1);
162	            }
163	            digits = "61" + cleaned;
164	        }
165	        if (!digits.matches("[0-9]{8,15}")) {
166	            throw new InvalidTelephoneException(telephone);
167	        }
168	        return "+" + digits;
169	    }
170	
171	    /**
172	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
173	     * multi-character top-level label. Deliberately lenient about the exact character set while still
174	     * rejecting values that are clearly not addresses (e.g. missing '@').
175	     */
176	    private static final java.util.regex.Pattern EMAIL_PATTERN =
177	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
178	
179	    /**
180	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
181	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
182	     * lower-cased before being stored and returned.
183	     *
184	     * @param email the raw email as submitted, may be {@code null}
185	     * @return the lower-cased email, or {@code null} when none was supplied
186	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
187	     */
188	    private String normalizeEmail(String email) {
189	        if (email == null || email.isBlank()) {
190	            return null;
191	        }
192	        String trimmed = email.trim();
193	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
194	            throw new InvalidEmailException(email);
195	        }
196	        return trimmed.toLowerCase(java.util.Locale.ROOT);
197	    }
198	
199	    /**
200	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
201	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
202	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
203	     * {@code "+61 412 345 678"}) are still treated as duplicates.
204	     *
205	     * @param telephone the E.164 telephone of the owner being created
206	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
207	     */
208	    private void rejectDuplicateTelephone(String telephone) {
209	        boolean duplicate = this.clinicService.findAllOwners().stream()
210	            .map(Owner::getTelephone)
211	            .filter(existing -> existing != null)
212	            .map(this::toE164OrNull)
213	            .filter(existing -> existing != null)
214	            .anyMatch(telephone::equals);
215	        if (duplicate) {
216	            throw new DuplicateTelephoneException(telephone);
217	        }
218	    }
219	
220	    /**
221	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
222	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
223	     */
224	    private String toE164OrNull(String telephone) {
225	        try {
226	            return normalizeTelephone(telephone);
227	        } catch (InvalidTelephoneException e) {
228	            return null;
229	        }
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
235	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
236	        if (currentOwner == null) {
237	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	        }
239	        currentOwner.setAddress(ownerFieldsDto.getAddress());
240	        currentOwner.setCity(ownerFieldsDto.getCity());
241	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
242	        currentOwner.setLastName(ownerFieldsDto.getLastName());
243	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
244	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
245	        this.clinicService.saveOwner(currentOwner);
246	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Transactional
251	    @Override
252	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
253	        Owner owner = this.clinicService.findOwnerById(ownerId);
254	        if (owner == null) {
255	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	        }
257	        this.clinicService.deleteOwner(owner);
258	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
259	    }
260	
261	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
262	    @Override
263	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
264	        Owner owner = this.clinicService.findOwnerById(ownerId);
265	        if (owner == null) {
266	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	        }
268	        HttpHeaders headers = new HttpHeaders();
269	        Pet pet = petMapper.toPet(petFieldsDto);
270	        owner.setId(ownerId);
271	        pet.setOwner(owner);
272	        pet.getType().setName(null);
273	        this.clinicService.savePet(pet);
274	        PetDto petDto = petMapper.toPetDto(pet);
275	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
276	            .buildAndExpand(pet.getId()).toUri());
277	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
278	    }
279	
280	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
281	    @Override
282	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
283	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
284	        if (currentOwner != null) {
285	            Pet currentPet = this.clinicService.findPetById(petId);
286	            if (currentPet != null) {
287	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
288	                currentPet.setName(petFieldsDto.getName());
289	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
290	                this.clinicService.savePet(currentPet);
291	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
292	            }
293	        }
294	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	    }
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Override
299	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
300	        HttpHeaders headers = new HttpHeaders();
301	        Visit visit = visitMapper.toVisit(visitFieldsDto);
302	        Pet pet = new Pet();
303	        pet.setId(petId);
304	        visit.setPet(pet);
305	        this.clinicService.saveVisit(visit);
306	        VisitDto visitDto = visitMapper.toVisitDto(visit);
307	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
308	            .buildAndExpand(visit.getId()).toUri());
309	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
310	    }
311	
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
316	        Owner owner = this.clinicService.findOwnerById(ownerId);
317	        if (owner != null) {
318	            Pet pet = owner.getPet(petId);
319	            if (pet != null) {
320	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
321	            }
322	        }
323	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
324	    }
325	}
